def run_subprocess(cmd: str, timeout: int = 30) -> str:
    """Run subprocess command."""
    import subprocess
    try:
        result = subprocess.run(
            cmd, shell=True, capture_output=True, text=True, timeout=timeout
        )
        return result.stdout + result.stderr
    except Exception:
        return ""


